"""Generate internal/ledger/op/unicode_tables.go and testdata/label_golden.json from CPython unicodedata.

Run: python3 -I internal/ledger/op/testdata/gen_unicode.py <out.go> <golden.json>
The stdlib has no Unicode normalization and golang.org/x/text is not an allowed dependency, so the
canonical decomposition, combining classes, primary composites and full case folding come from here.
"""
import json
import random
import subprocess
import sys
import unicodedata

decomp, ccc, compose, fold = {}, {}, {}, {}
for cp in range(0x110000):
    if 0xD800 <= cp <= 0xDFFF:
        continue
    ch = chr(cp)
    c = unicodedata.combining(ch)
    if c:
        ccc[cp] = c
    d = unicodedata.decomposition(ch)
    if d and not d.startswith("<"):
        parts = [int(x, 16) for x in d.split()]
        decomp[cp] = parts
        if len(parts) == 2 and unicodedata.normalize("NFC", ch) == ch and unicodedata.combining(chr(parts[0])) == 0:
            compose[(parts[0], parts[1])] = cp
    f = ch.casefold()
    if f != ch:
        fold[cp] = [ord(x) for x in f]

def runes(xs):
    return "{" + ",".join("0x%X" % x for x in xs) + "}"

out = ["// Code generated by testdata/gen_unicode.py from CPython unicodedata %s; DO NOT EDIT." % unicodedata.unidata_version,
       "", "package op", "", "// UnicodeVersion is the Unicode version the tables were generated from.",
       'const UnicodeVersion = "%s"' % unicodedata.unidata_version, "",
       "var canonDecomp = map[rune][]rune{"]
out += ["\t0x%X: %s," % (k, runes(v)) for k, v in sorted(decomp.items())]
out += ["}", "", "var combClass = map[rune]uint8{"]
out += ["\t0x%X: %d," % (k, v) for k, v in sorted(ccc.items())]
out += ["}", "", "var primaryComposite = map[[2]rune]rune{"]
out += ["\t{0x%X, 0x%X}: 0x%X," % (a, b, v) for (a, b), v in sorted(compose.items())]
out += ["}", "", "var caseFold = map[rune][]rune{"]
out += ["\t0x%X: %s," % (k, runes(v)) for k, v in sorted(fold.items())]
out += ["}", ""]
src = subprocess.run(["gofmt"], input="\n".join(out), capture_output=True, text=True, check=True).stdout
open(sys.argv[1], "w").write(src)

rng = random.Random(35695)
pool = [chr(c) for c in list(range(0x20, 0x7F)) + list(range(0xC0, 0x250)) + list(range(0x300, 0x370))
        + list(range(0x1E00, 0x1F00)) + list(range(0xAC00, 0xAC40)) + list(range(0x1100, 0x1176))
        + [0x1E9E, 0xDF, 0x212B, 0x2126, 0xFB01, 0x130, 0x3A3, 0x3C2, 0x345, 0x0F73, 0x1D15E]]
cases = ["Café", "Café", "  STRASSE ", "straße", "Ångström", "ﬁx", "각", "ę̧́"]
for _ in range(400):
    cases.append("".join(rng.choice(pool) for _ in range(rng.randint(1, 8))))
golden = [{"in": s, "nfc": unicodedata.normalize("NFC", s),
           "key": unicodedata.normalize("NFC", unicodedata.normalize("NFC", s).strip().casefold())} for s in cases]
open(sys.argv[2], "w").write(json.dumps({"seed": 35695, "unicode": unicodedata.unidata_version, "cases": golden},
                                        ensure_ascii=True, indent=0) + "\n")
